            /** Format: date-time */
            at: string;
            /** @enum {string} */
            trigger: "schedule" | "manual" | "reset";
            ok: boolean;
            file?: string;
            /** Format: int64 */
            bytes?: number;
            /** Format: int64 */
            ms: number;
            error?: string;
